import unittest
from solution import fib

class T(unittest.TestCase):
    def test_zero(self):
        self.assertEqual(fib(0), 0)
    def test_one(self):
        self.assertEqual(fib(1), 1)
    def test_ten(self):
        self.assertEqual(fib(10), 55)
    def test_negative(self):
        with self.assertRaises(ValueError):
            fib(-1)
